    return this.http
      .put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today }, {
        headers: this.session.headers(),
      })
      .pipe(map((s) => (this.show(s), s.today)));
  }

  private show(s: SheetView): string {
    this.current.set(s.id);
    this.currentToday.set(s.today);
    return s.id;
  }
}
