      <p role="status">Loading sheet…</p>
    } @else if (sheets.sheetId(); as current) {
      <p>Sheet: <span data-testid="sheet-current-id">{{ current }}</span></p>
      <app-sheet-today />
      <app-rates />
      <app-people />
